@[simp, grind =] theorem orderedInsertM_cons (a b : α) (l : List α) :
    orderedInsertM r a (b :: l) = do
      if ← r a b then return a :: b :: l else return b :: (← orderedInsertM r a l)

@[simp] theorem cons_mergeM_cons (x y : α) (xs ys : List α) (le : α → α → m Bool) :
    mergeM (x :: xs) (y :: ys) le = do
      if ← le x y then
        return x :: (← mergeM xs (y :: ys) le)
      else
        return y :: (← mergeM (x :: xs) ys le)

theorem comp_assoc
    {i₁ : Interpretation σ U₁}
    {i₂ : Interpretation σ U₂}
    {i₃ : Interpretation σ U₃}
    {i₄ : Interpretation σ U₄}
    (outer : Homomorphism i₃ i₄)
    (middle : Homomorphism i₂ i₃)
    (inner : Homomorphism i₁ i₂) :
    (outer.comp middle).comp inner = outer.comp (middle.comp inner)

@[simp] theorem comp_id
    {source : Interpretation σ U₁}
    {target : Interpretation σ U₂}
    (homomorphism : Homomorphism source target) :
    homomorphism.comp (Homomorphism.id source) = homomorphism

@[simp] theorem comp_map
    {i₁ : Interpretation σ U₁}
    {i₂ : Interpretation σ U₂}
    {i₃ : Interpretation σ U₃}
    (outer : Homomorphism i₂ i₃)
    (inner : Homomorphism i₁ i₂) :
    (outer.comp inner).map = outer.map ∘ inner.map

@[ext] theorem ext
    {source : Interpretation σ U₁}
